/// <summary>
/// PaffH 06.02.25
/// </summary>
public class NDXTmpCustomerAllianceBlock extends common
{
}

Method.Source:
/// <summary>
/// PaffH 06.02.25
/// </summary>
/// <param name = "_signature">NDXUmsSignature</param>
/// <param name = "_alliance">NDXAlliance</param>
/// <param name = "_company">NDXCompanys</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXTmpCustomerAllianceBlock</returns>
public static NDXTmpCustomerAllianceBlock find(NDXUmsSignature _signature, NDXAlliance _alliance, NDXCompanys _company, boolean _forUpdate = true)
{
    NDXTmpCustomerAllianceBlock nDXTmpCustomerAllianceBlock;
    nDXTmpCustomerAllianceBlock.selectForUpdate(_forUpdate);
    select firstonly nDXTmpCustomerAllianceBlock
        where nDXTmpCustomerAllianceBlock.UmsSignature == _signature
        && nDXTmpCustomerAllianceBlock.Alliance == _alliance
        && nDXTmpCustomerAllianceBlock.Company == _company;
    return nDXTmpCustomerAllianceBlock;
}

/// <summary>
/// PaffH 06.02.25
/// </summary>
/// <param name = "_signature">NDXUmsSignature</param>
/// <param name = "_alliance">NDXAlliance</param>
/// <param name = "_company">NDXCompanys</param>
/// <param name = "_insert">boolean</param>
/// <returns>NDXTmpCustomerAllianceBlock</returns>
public static NDXTmpCustomerAllianceBlock findOrCreate(NDXUmsSignature _signature, NDXAlliance _alliance, NDXCompanys _company, boolean _insert = true)
{
    NDXTmpCustomerAllianceBlock nDXTmpCustomerAllianceBlock = NDXTmpCustomerAllianceBlock::find(_signature, _alliance, _company, true);
    if (!nDXTmpCustomerAllianceBlock)
    {
        nDXTmpCustomerAllianceBlock.UmsSignature = _signature;
        nDXTmpCustomerAllianceBlock.Alliance = _alliance;
        nDXTmpCustomerAllianceBlock.Company = _company;
        if (_insert)
        {
            nDXTmpCustomerAllianceBlock.insert();
        }
    }
    return nDXTmpCustomerAllianceBlock;
}

/// <summary>
/// PaffH 06.02.25
/// </summary>
/// <param name = "_signature">NDXUmsSignature</param>
/// <param name = "_alliance"></param>
/// <param name = "_company"></param>
/// <returns></returns>
public static boolean unblock(NDXUmsSignature _signature, NDXAlliance _alliance, NDXCompanys _company)
{
    NDXTmpCustomerAllianceBlock nDXTmpCustomerAllianceBlock = NDXTmpCustomerAllianceBlock::find(_signature, _alliance, _company);
    if (nDXTmpCustomerAllianceBlock)
    {
        nDXTmpCustomerAllianceBlock.Blocked = NoYes::No;
        ttsbegin;
        nDXTmpCustomerAllianceBlock.update();
        ttscommit;
        return true;
    }
    return false;
}

/// <summary>
/// PaffH 06.02.25
/// </summary>
/// <param name = "_signature">NDXUmsSignature</param>
/// <param name = "_alliance">NDXAlliance</param>
/// <param name = "_company">NDXCompanys</param>
/// <param name = "_blockIfNotFound">boolean</param>
/// <param name = "_waitIfBlocked">int</param>
/// <param name = "_throwErrorNotUnblockedInTime">boolean</param>
/// <returns>NDXRecordBlockContract</returns>
public static NDXRecordBlockContract blockCheck(
    NDXUmsSignature _signature, 
    NDXAlliance _alliance, 
    NDXCompanys _company, 
    boolean _blockIfNotFound = true,
    int _waitSecondsIfBlocked = 10 * 60,
    boolean _throwErrorNotUnblockedInTime = true)
{
    NDXRecordBlockContract retContract = NDXRecordBlockContract::construct();
    NDXTmpCustomerAllianceBlock nDXTmpCustomerAllianceBlock = NDXTmpCustomerAllianceBlock::find(_signature, _alliance, _company, false);
    retContract.parmFoundUnblocked(nDXTmpCustomerAllianceBlock == null || nDXTmpCustomerAllianceBlock.Blocked == NoYes::No);
    retContract.parmBlocked(nDXTmpCustomerAllianceBlock.Blocked);

    if (_blockIfNotFound && !nDXTmpCustomerAllianceBlock)
    {
        System.Exception ex;
        try
        {
            nDXTmpCustomerAllianceBlock = NDXTmpCustomerAllianceBlock::findOrCreate(_signature, _alliance, _company, false);
            nDXTmpCustomerAllianceBlock.Blocked = NoYes::Yes;
            ttsbegin;
            nDXTmpCustomerAllianceBlock.write();
            ttscommit;
        }
        catch (ex)
        {
            Error(ex.Message);
        }
        finally
        {
            retContract.parmBlocked(nDXTmpCustomerAllianceBlock.Blocked);
        }
    }
    else if (nDXTmpCustomerAllianceBlock != null 
        && nDXTmpCustomerAllianceBlock.Blocked == NoYes::Yes
        && _waitSecondsIfBlocked)
    {
        int sleepTime = 2000;
        int maxRuns = real2int(_waitSecondsIfBlocked / (sleepTime / 1000));
        for (int i = 1; i <= maxRuns; i++)
        {
            sleep(sleepTime);
            nDXTmpCustomerAllianceBlock.reread();
            if (nDXTmpCustomerAllianceBlock.Blocked == NoYes::No)
            {
                break;
            }
        }
        retContract.parmBlocked(nDXTmpCustomerAllianceBlock.Blocked);
        if (_throwErrorNotUnblockedInTime && nDXTmpCustomerAllianceBlock.Blocked == NoYes::Yes)
        {
            throw Error(strFmt("@NDXBase:NDXRecordUnlockNotSucessful", _signature, _alliance, _company));
        }
    }
    return retContract;
}
